            if (b[r][i] == ch) return false;
            if (b[i][c] == ch) return false;
            int br = 3*(r/3)+i/3, bc = 3*(c/3)+i%3;
            if (b[br][bc] == ch) return false;
        }
        return true;
    }
    bool backtrack(vector<vector<char>>& b) {
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                if (b[r][c] == '.') {
                    for (char ch = '1'; ch <= '9'; ++ch) {
                        if (isValid(b, r, c, ch)) {
                            b[r][c] = ch;
                            if (backtrack(b)) return true;
                            b[r][c] = '.';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }
};

