class Solution {
public:
    void solveSudoku(vector<vector<char>>& board) {
        memset(rows, 0, sizeof(rows));
        memset(cols, 0, sizeof(cols));
        memset(boxes, 0, sizeof(boxes));
        empties.clear();
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                if (board[r][c] == '.') empties.emplace_back(r, c);
                else {
                    int d = board[r][c] - '1';
                    int bit = 1 << d;
                    rows[r] |= bit;
                    cols[c] |= bit;
                    boxes[(r/3)*3 + c/3] |= bit;
                }
            }
        }
        dfs(board, 0);
    }
private:
    int rows[9], cols[9], boxes[9];
    vector<pair<int,int>> empties;
    bool dfs(vector<vector<char>>& b, int k) {
        if (k == (int)empties.size()) return true;
        int best = k, bestMask = 0, minCnt = 10;
        for (int i = k; i < (int)empties.size(); ++i) {
            int r = empties[i].first, c = empties[i].second;
            int bi = (r/3)*3 + c/3;
            int mask = ~(rows[r] | cols[c] | boxes[bi]) & 0x1FF;
            int cnt = __builtin_popcount((unsigned)mask);
            if (cnt < minCnt) {
                minCnt = cnt;
                best = i;
                bestMask = mask;
                if (cnt == 1) break;
            }
        }
        if (minCnt == 0) return false;
        swap(empties[k], empties[best]);
        int r = empties[k].first, c = empties[k].second;
        int bi = (r/3)*3 + c/3;
        int mask = ~(rows[r] | cols[c] | boxes[bi]) & 0x1FF;
        while (mask) {
            int bit = mask & -mask;
            int d = __builtin_ctz((unsigned)bit);
            b[r][c] = char('1' + d);
            rows[r] |= bit; cols[c] |= bit; boxes[bi] |= bit;
            if (dfs(b, k + 1)) return true;
            rows[r] ^= bit; cols[c] ^= bit; boxes[bi] ^= bit;
            b[r][c] = '.';
            mask ^= bit;
        }
        swap(empties[k], empties[best]);
        return false;
    }
};

