class Solution {
    private int[] rows = new int[9];
    private int[] cols = new int[9];
    private int[] boxes = new int[9];
    private int[][] empties = new int[81][2];
    private int m = 0;
    public void solveSudoku(char[][] board) {
        m = 0;
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    empties[m][0] = r; empties[m][1] = c; m++;
                } else {
                    int d = board[r][c] - '1';
                    int bit = 1 << d;
                    rows[r] |= bit;
                    cols[c] |= bit;
                    boxes[(r/3)*3 + c/3] |= bit;
                }
            }
        }
        dfs(board, 0);
    }
    private boolean dfs(char[][] b, int k) {
        if (k == m) return true;
        int best = k, minCnt = 10;
        for (int i = k; i < m; i++) {
            int r = empties[i][0], c = empties[i][1];
            int bi = (r/3)*3 + c/3;
            int mask = ~(rows[r] | cols[c] | boxes[bi]) & 0x1FF;
            int cnt = Integer.bitCount(mask);
            if (cnt < minCnt) {
                minCnt = cnt;
                best = i;
                if (cnt == 1) break;
            }
        }
        if (minCnt == 0) return false;
        swap(k, best);
        int r = empties[k][0], c = empties[k][1];
        int bi = (r/3)*3 + c/3;
        int mask = ~(rows[r] | cols[c] | boxes[bi]) & 0x1FF;
        while (mask != 0) {
            int bit = mask & -mask;
            int d = Integer.numberOfTrailingZeros(bit);
            b[r][c] = (char)('1' + d);
            rows[r] |= bit; cols[c] |= bit; boxes[bi] |= bit;
            if (dfs(b, k + 1)) return true;
            rows[r] ^= bit; cols[c] ^= bit; boxes[bi] ^= bit;
            b[r][c] = '.';
            mask ^= bit;
        }
        swap(k, best);
        return false;
    }
    private void swap(int i, int j) {
        int tr = empties[i][0], tc = empties[i][1];
        empties[i][0] = empties[j][0]; empties[i][1] = empties[j][1];
        empties[j][0] = tr; empties[j][1] = tc;
    }
}
